429:   index = -ENOENT;
430:   for (attempt = 0; attempt < 3 && index < 0; attempt++)
431:     {
432:       if (g_cancel) return -EINTR;
433:       ret = wifi_scan(band, report);
434:       if (ret < 0 && ret != -ENODATA)
435:         {
436:           return ret;
437:         }
438: 
439:       index = wifi_find_ssid(report, ssid, wanted_band);
440:       if (index < 0 && attempt + 1 < 3)
