458:   else ret = wifi_password(password);
459:   if (ret < 0)
460:     {
461:       wifi_clear(password, sizeof(password));
462:       return ret;
463:     }
464: 
465:   if (strlen(password) < 8 || strlen(password) > 63)
466:     { ret = -EINVAL; goto done; }
467:   snprintf(command, sizeof(command), "wpa2=%d,%s", index, password);
468:   if (g_cancel) { ret = -EINTR; goto done; }
469:   ret = wifi_control(command);
470:   wifi_clear(command, sizeof(command));
471:   if (ret < 0)
472:     {
473:       goto done;
474:     }
475: 
476:   puts("Associating, completing WPA2 and waiting for DHCP...");
477:   for (waited = 0; waited < 90; waited++)
