                         A733_AIC_USB_TYPE_CMD)
        {
          continue;
        }

      message_id = a733_getle16(g_wifi_aic_rx + 4);
      parameter_length = a733_getle16(g_wifi_aic_rx + 10);
      if (actual < 16u + parameter_length)
        {
          continue;
        }

